set-variable.value:
@{
    if (!context.Variables.ContainsKey("byokCallerAuthenticated") || !(bool)context.Variables["byokCallerAuthenticated"]
        || (context.Variables.ContainsKey("byokCallerAccountingApplied") && (bool)context.Variables["byokCallerAccountingApplied"])) { return "invalid"; }
    foreach (var name in new[] { "callerAuthMethod", "callerIssuer", "callerSubject", "callerPrincipalKey" }) {
      if (!context.Variables.ContainsKey(name) || string.IsNullOrWhiteSpace((string)context.Variables[name])) { return "invalid"; }
    }
    var method = (string)context.Variables["callerAuthMethod"];
    var issuer = (string)context.Variables["callerIssuer"];
    var subject = (string)context.Variables["callerSubject"];
    var expectedPrincipal = method + ":" + issuer.Length + ":" + issuer + ":" + subject;
    if ((string)context.Variables["callerPrincipalKey"] != expectedPrincipal) { return "invalid"; }
    if (method == "subscriptionKey") {
      return issuer == "apim" && context.Subscription != null && subject == context.Subscription.Id ? "native" : "invalid";
    }
    return (method == "entraJwt" || method == "oktaJwt")
        && context.Variables.ContainsKey("byokJwtValidated") && (bool)context.Variables["byokJwtValidated"] ? "jwt" : "invalid";
  }
